const d1Result = $node["Pull D1 Player Telemetry"].json;
const aiAdvice = $input.first().json.message?.content || $input.first().json.text || 'Keep grinding your mechanical flick alignment.';
const players = d1Result.result?.[0]?.results || d1Result.result?.results || [];

let markdown = "### 🎯 AimSync Weekly Retention & Community Progression Digest\n\n";
markdown += "**AI Tactical Coach Summary:**\n" + aiAdvice + "\n\n";
markdown += "#### 🏆 Weekly Leaderboard & Rewards (+500 Weekly Bonus XP Claimed)\n\n";
markdown += "| Rank | Username | Level | Sessions | Avg Acc | Peak Combo | Weekly XP |\n";
markdown += "| :--- | :--- | :--- | :--- | :--- | :--- | :--- |\n";

players.forEach((p, idx) => {
  markdown += `| ${idx + 1} | **${p.username}** | Lvl ${p.current_level} | ${p.total_sessions} | ${p.avg_accuracy}% | ${p.peak_combo} | +${(p.weekly_xp_gained + 500).toLocaleString()} XP |\n`;
});

markdown += "\n*Automated Sunday Report generated by Cloudflare D1 & n8n Progression Engine.*";

return {
  markdownReport: markdown,
  playerCount: players.length
};

